static const lv_image_dsc_t stat_icon_clock_64_dsc = {
    {LV_IMAGE_HEADER_MAGIC, LV_COLOR_FORMAT_RGB565A8, 0, 64, 64, 128, 0},
    sizeof(stat_icon_clock_64_data),
    stat_icon_clock_64_data,
    nullptr,
    nullptr
};

const lv_image_dsc_t *stat_icon_descriptor(StatIconKind kind) {
    switch(kind) {
        case StatIconKind::Gamepad: return &stat_icon_gamepad_64_dsc;
        case StatIconKind::Percent: return &stat_icon_percent_64_dsc;
        case StatIconKind::Medal: return &stat_icon_medal_64_dsc;
        case StatIconKind::Clock: return &stat_icon_clock_64_dsc;
    }
    return &stat_icon_gamepad_64_dsc;
}

